### Código C++ Modificado

```cpp
#include <iostream>
#include <fstream>
#include <sstream> // Necessário para processar a entrada do usuário
#include <map>     // Usaremos um mapa para armazenar Filename -> Hash
#include <vector>
#include <string>
#include <algorithm> // Para std::find

// Bibliotecas Crypto++
#include <cryptopp/keccak.h>
#include <cryptopp/hex.h>
#include <cryptopp/files.h>

namespace fs = std::filesystem;

/**
 * @brief Calcula o hash Keccak-512 de um arquivo.
 * @param filePath Caminho completo do arquivo.
 * @return O hash em formato hexadecimal.
 */
std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    try {
        CryptoPP::FileSource(filePath.c_str(), true,
            new CryptoPP::HashFilter(hash,
                new CryptoPP::HexEncoder(
                    new CryptoPP::StringSink(digest), true)));
    } catch (const CryptoPP::Exception& e) {
        std::cerr << "Erro ao processar o arquivo " << filePath << ": " << e.what() << std::endl;
        return ""; // Retorna string vazia em caso de falha
    }
    return digest;
}

/**
 * @brief Função auxiliar para dividir uma string por um delimitador (e.g., vírgula).
 */
std::vector<int> parseInput(const std::string& input) {
    std::vector<int> selections;
    std::stringstream ss(input);
    std::string segment;

    while (std::getline(ss, segment, ',')) {
        try {
            // Remove espaços em branco antes de converter
            segment.erase(0, segment.find_first_not_of(' '));
            segment.erase(segment.find_last_not_of(' ') + 1);

            // Tenta converter a parte em um número
            size_t pos;
            int number = std::stoi(segment, &pos);

            if (pos == segment.length()) { // Garante que toda a string foi um número
                selections.push_back(number);
            }
        } catch (...) {
            // Ignora segmentos que não são números
        }
    }
    return selections;
}


int main() {
    // Estrutura para armazenar todos os arquivos encontrados: { NomeArquivo -> Hash }
    std::map<std::string, std::string> fileHashes;
    std::vector<std::string> extensions = { ".exe", ".dll", ".asi" };

    std::cout << "===================================================" << std::endl;
    std::cout << "FASE 1: Calculando Hashes para arquivos selecionados..." << std::endl;

    // ===============================================================
    // PASSO 1: ITERAR, CALCULAR E ARMAZENAR TODOS OS HASHS
    // ===============================================================
    for (const auto& entry : fs::directory_iterator(fs::current_path())) {
        if (entry.is_regular_file()) {
            std::string extension = entry.path().extension().string();

            // Verifica se a extensão está na lista
            bool isTargetFile = std::find(extensions.begin(), extensions.end(), extension) != extensions.end();

            if (isTargetFile) {
                std::string filePath = entry.path().string();
                std::string filename = entry.path().filename().string();

                std::string hash = calculateKeccak512(filePath);

                if (!hash.empty()) {
                    fileHashes[filename] = hash;
                    std::cout << "  [OK] " << filename << std::endl;
                }
            }
        }
    }

    if (fileHashes.empty()) {
        std::cerr << "\nNenhum arquivo elegível encontrado. Encerrando." << std::endl;
        return 0;
    }

    // ===============================================================
    // PASSO 2: EXIBIR LISTA E SOLICITAR SELEÇÃO DO USUÁRIO
    // ===============================================================
    std::cout << "\n===================================================" << std::endl;
    std::cout << "FASE 2: Seleção de Arquivos para rTales.ini" << std::endl;
    std::cout << "===================================================" << std::endl;

    // Exibe a lista numerada
    int index = 1;
    for (const auto& pair : fileHashes) {
        std::cout << "[" << index << "] " << pair.first << " (Hash: " << pair.second.substr(0, 10) << "...) " << std::endl;
        index++;
    }

    std::cout << "\n===================================================" << std::endl;
    std::cout << "Insira os números dos arquivos que deseja no rTales.ini (ex: 1,3,5): ";
    std::string userInput;
    std::getline(std::cin, userInput);

    // Processa a entrada do usuário
    std::vector<int> selectedIndices = parseInput(userInput);

    // ===============================================================
    // PASSO 3A: GERAR rTalesHash.txt (Todos os hashes)
    // ===============================================================
    std::cout << "\n===================================================" << std::endl;
    std::cout << "FASE 3A: Gerando rTalesHash.txt (Todos os arquivos)..." << std::endl;
    std::ofstream allHashFile("rTalesHash.txt");
    if (allHashFile.is_open()) {
        for (const auto& pair : fileHashes) {
            allHashFile << "\"" << pair.first << "\" : " << pair.second << std::endl;
        }
        allHashFile.close();
        std::cout << "Arquivo rTalesHash.txt criado com sucesso." << std::endl;
    } else {
        std::cerr << "ERRO: Não foi possível abrir rTalesHash.txt para escrita." << std::endl;
    }


    // ===============================================================
    // PASSO 3B: GERAR rTales.ini (Apenas os selecionados)
    // ===============================================================
    std::cout << "\n===================================================" << std::endl;
    std::cout << "FASE 3B: Gerando rTales.ini (Arquivos selecionados)..." << std::endl;
    std::ofstream iniFile("rTales.ini");
    if (!iniFile.is_open()) {
        std::cerr << "Erro ao abrir o arquivo rTales.ini!" << std::endl;
        return 1;
    }

    for (int indexValue : selectedIndices) {
        if (indexValue > 0 && indexValue <= fileHashes.size()) {
            // Como o mapa está ordenado por nome, precisamos encontrar o item correto baseado no índice
            auto it = fileHashes.begin();
            std::advance(it, indexValue - 1); // Move o iterator para o índice desejado

            iniFile << "\"" << it->first << "\" : " << it->second << std::endl;
        }
    }
    iniFile.close();
    std::cout << "Arquivo rTales.ini criado com sucesso, contendo apenas os arquivos selecionados." << std::endl;
    std::cout << "===================================================" << std::endl;

    return 0;
}
